export class Router{constructor({mount:t,routes:e}){this.mount=t,this.routes=e,window.addEventListener("hashchange",()=>this.render()),window.addEventListener("load",()=>this.render())}raw(){return location.hash.replace(/^#/,"")}parse(){const t=this.raw()||"/",[e,r=""]=t.split("?");return{path:e,query:new URLSearchParams(r)}}go(t,e){const r=e?"?"+new URLSearchParams(e).toString():"";location.hash=t+r}async render(){const{path:t,query:e}=this.parse(),r=this.routes[t]||this.routes["/404"];if(!r)return;const n=await r();this.mount.innerHTML=n,document.dispatchEvent(new CustomEvent("spa:render",{detail:{path:t,query:e}}))}}